    div#sys-tutor .sys-input-val:focus, div#sys-tutor .sys-input-coef:focus { outline: none !important; border-color: #f57c00 !important; background-color: #fff3e0 !important; box-shadow: 0 0 5px rgba(245, 124, 0, 0.5) !important; }

    /* BOTONES SECUNDARIOS INVERTIDOS ("¿Bien?" y "Comprobar") */
