    div#sys-tutor .sys-btn-check:hover { transform: scale(1.05) !important; background-color: #f57c00 !important; color: #ffffff !important; border-color: #f57c00 !important; }
    div#sys-tutor .sys-btn-check:disabled { background-color: #f9f9f9 !important; border-color: #ccc !important; color: #aaa !important; cursor: not-allowed !important; transform: none !important; }

    div#sys-tutor .sys-feedback { font-weight: bold; margin-left: 10px; font-size: 0.95em; }
    div#sys-tutor .sys-success { color: #28a745 !important; }
    div#sys-tutor .sys-error { color: #d32f2f !important; }

    div#sys-tutor .frac-css { display: inline-block; text-align: center; vertical-align: middle; font-size: 0.95em; margin: 0 2px; }
    div#sys-tutor .frac-css span { display: block; padding: 0.1em 0.2em; line-height: 1.1; }
    div#sys-tutor .frac-css span.fdn { border-top: 1px solid #333; }
