<p>
<script>
    // --- MOTOR DE FRACCIONES EXACTAS ---
    function gcd(a, b) {
        a = Math.abs(a); b = Math.abs(b);
        while (b) { let t = b; b = a % b; a = t; }
        return a || 1;
    }
    function simplify(n, d) {
        if (n === 0) return {n: 0, d: 1};
        if (d < 0) { n = -n; d = -d; }
        let g = gcd(n, d);
        return {n: n / g, d: d / g};
    }
    function fAdd(a, b) { return simplify(a.n * b.d + b.n * a.d, a.d * b.d); }
    function fSub(a, b) { return simplify(a.n * b.d - b.n * a.d, a.d * b.d); }
    function fMul(a, b) { return simplify(a.n * b.n, a.d * b.d); }
    function fDiv(a, b) { return simplify(a.n * b.d, a.d * b.n); }
    function fEqual(a, b) { return a.n * b.d === b.n * a.d; }
    function fIsZero(a) { return a.n === 0; }

    function fFormatTerm(f, variable) {
        if (fIsZero(f)) return "";
        let sign = f.n > 0 ? "+" : "-";
        let absF = {n: Math.abs(f.n), d: f.d};
        let coef = formatFracVisual(absF);
        if (absF.n === 1 && absF.d === 1) coef = ""; // Omit 1x
        return ` ${sign} ${coef}${variable}`;
    }

    function parseFracObj(valStr) {
        if(!valStr || valStr.trim() === '') return null;
        valStr = valStr.replace(/\s+/g, '').replace(',', '.');
        if(valStr.includes('/')) {
            let parts = valStr.split('/');
            if(parts.length !== 2) return null;
            let num = parseInt(parts[0]), den = parseInt(parts[1]);
            if(isNaN(num) || isNaN(den) || den === 0) return null;
            return simplify(num, den);
        }
        let val = parseFloat(valStr);
        if(isNaN(val)) return null;
        let str = val.toString();
        if (!str.includes('.')) return {n: parseInt(val), d: 1};
        let decs = str.split('.')[1].length;
        let d = Math.pow(10, decs);
        return simplify(Math.round(val * d), d);
    }

    function formatFracVisual(f) {
        if (f.n === 0) return "0";
        if (f.d === 1) return f.n.toString();
        let sign = f.n < 0 ? "-" : "";
        return `${sign}<div class="frac-css"><span class="fnum">${Math.abs(f.n)}</span><span class="fdn">${f.d}</span></div>`;
    }

    // --- VARIABLES GLOBALES ---
    let sysMatrix = []; 
    let initialMatrix = [];
    let rowsCompletedStep1 = 0;

    // --- GENERACIÓN SEGURA ---
    function sysGenerar() {
        let isPro = document.querySelector('input[name="sys-dif"]:checked').value === 'pro';

        let valid = false;
        let mat = [];

        while(!valid) {
            mat = Array(3).fill().map(()=>Array(4).fill({n:0, d:1}));

            if (!isPro) {
                let solX = Math.floor(Math.random() * 7) - 3;
                let solY = Math.floor(Math.random() * 7) - 3;
                let solZ = Math.floor(Math.random() * 7) - 3;

                let u11 = Math.floor(Math.random() * 3) + 1; // 1, 2 or 3
                let u22 = (Math.random() > 0.5 ? 1 : -1) * (Math.floor(Math.random() * 2) + 1);
                let u33 = (Math.random() > 0.5 ? 1 : -1) * (Math.floor(Math.random() * 2) + 1);

                let u12 = Math.floor(Math.random() * 5) - 2;
                let u13 = Math.floor(Math.random() * 5) - 2;
                let u23 = Math.floor(Math.random() * 5) - 2;

                let b3 = u33 * solZ;
                let b2 = u22 * solY + u23 * solZ;
                let b1 = u11 * solX + u12 * solY + u13 * solZ;

                mat[0] = [{n:u11,d:1}, {n:u12,d:1}, {n:u13,d:1}, {n:b1,d:1}];
                mat[1] = [{n:0,d:1}, {n:u22,d:1}, {n:u23,d:1}, {n:b2,d:1}];
                mat[2] = [{n:0,d:1}, {n:0,d:1}, {n:u33,d:1}, {n:b3,d:1}];

                for(let j=0; j<2; j++) {
                    for(let i=j+1; i<3; i++) {
                        let k = Math.floor(Math.random() * 3) - 1; 
                        if(k !== 0) {
                            for(let c=0; c<4; c++) {
                                mat[i][c] = fAdd(mat[i][c], fMul({n:k, d:1}, mat[j][c]));
                            }
                        }
                    }
                }
                valid = true;
            } else {
                for(let i=0; i<3; i++){
                    for(let j=0; j<4; j++){
                        mat[i][j] = {n: Math.floor(Math.random() * 9) - 4, d: 1};
                    }
                }

                let temp = JSON.parse(JSON.stringify(mat));
                valid = true;
                for(let p=0; p<3; p++) {
                    if(fIsZero(temp[p][p])) { valid = false; break; }
                    for(let r=p+1; r<3; r++) {
                        let factor = fDiv(temp[r][p], temp[p][p]);
                        for(let c=p; c<4; c++) {
                            temp[r][c] = fSub(temp[r][c], fMul(factor, temp[p][c]));
                        }
                    }
                }
            }
        }

        sysMatrix = JSON.parse(JSON.stringify(mat));
        initialMatrix = JSON.parse(JSON.stringify(mat));
        sysUpdateDisplay();
        sysPrintEquations();
        sysResetUI();
    }

    function sysPrintEquations() {
        let eqHtml = "";
        for(let i=0; i<3; i++) {
            let terms = [];
            if(!fIsZero(initialMatrix[i][0])) terms.push(fFormatTerm(initialMatrix[i][0], "x"));
            if(!fIsZero(initialMatrix[i][1])) terms.push(fFormatTerm(initialMatrix[i][1], "y"));
            if(!fIsZero(initialMatrix[i][2])) terms.push(fFormatTerm(initialMatrix[i][2], "z"));

            let eq = terms.join("").trim();
            if(eq.startsWith("+")) eq = eq.substring(1).trim();
            if(eq === "") eq = "0";

            eqHtml += `<div>${eq} = ${formatFracVisual(initialMatrix[i][3])}</div>`;
        }
        document.getElementById('sys-equations-display').innerHTML = eqHtml;
    }

    function sysUpdateDisplay() {
        for(let i=0; i<3; i++) {
            for(let j=0; j<4; j++) {
                let cell = document.getElementById(`sys-m${i}${j}`);
                cell.innerHTML = formatFracVisual(sysMatrix[i][j]);
                cell.style.color = "#333";
                cell.style.fontWeight = "normal";
            }
        }
    }

    function sysHighlight(pivotCol, targetRow) {
        sysUpdateDisplay();
        let piv = document.getElementById(`sys-m${pivotCol}${pivotCol}`);
        piv.style.color = "#f57c00";
        piv.style.fontWeight = "bold";

        if(targetRow !== null) {
            let targ = document.getElementById(`sys-m${targetRow}${pivotCol}`);
            targ.style.color = "#d32f2f";
            targ.style.fontWeight = "bold";
        }
    }

    function sysResetUI() {
        document.getElementById('sys-paso1').style.display = 'block';
        document.getElementById('sys-paso2').style.display = 'none';
        document.getElementById('sys-paso3').style.display = 'none';

        let inputs = document.querySelectorAll('#sys-tutor input[type="text"]');
        inputs.forEach(inp => { inp.value = ''; inp.disabled = false; });

        let btns = document.querySelectorAll('#sys-tutor .sys-btn-check');
        btns.forEach(btn => { btn.disabled = false; btn.style.display = 'inline-block'; });

        let feedbacks = document.querySelectorAll('#sys-tutor .sys-feedback');
        feedbacks.forEach(fb => fb.innerHTML = '');
        document.getElementById('sys-final-msg').style.display = 'none';
        document.getElementById('box-sol-y').style.display = 'none';
        document.getElementById('box-sol-x').style.display = 'none';

        document.getElementById('row-p1a').style.display = 'none';
        document.getElementById('row-p1b').style.display = 'none';
        document.getElementById('row-p2').style.display = 'none';

        rowsCompletedStep1 = 0;
        sysHighlight(0, 1);
        document.getElementById('sys-m20').style.color = "#d32f2f"; document.getElementById('sys-m20').style.fontWeight = "bold";
    }

    // --- COMPROBADORES ---
    function sysCheckOp(targetRow, pivotCol, idKTarget, idKPivot, idFeedback, idRowContainer) {
        let kTarg = parseFracObj(document.getElementById(idKTarget).value);
        let kPiv = parseFracObj(document.getElementById(idKPivot).value);
        let fb = document.getElementById(idFeedback);

        if(!kTarg || !kPiv) { fb.innerHTML = '<span class="sys-error">Faltan datos</span>'; return; }
        if(fIsZero(kTarg)) { fb.innerHTML = '<span class="sys-error">Coeficiente fila objetivo no puede ser 0</span>'; return; }

        let valTarget = sysMatrix[targetRow][pivotCol];
        let valPivot = sysMatrix[pivotCol][pivotCol];

        let res = fAdd(fMul(kTarg, valTarget), fMul(kPiv, valPivot));

        if (fIsZero(res)) {
            fb.innerHTML = '<span class="sys-success">¡Operación válida!</span>';
            document.getElementById(idRowContainer).style.display = 'flex';
            document.getElementById(idKTarget).disabled = true;
            document.getElementById(idKPivot).disabled = true;
        } else {
            fb.innerHTML = '<span class="sys-error">No elimina la incógnita.</span>';
        }
    }

    function sysCheckRow(targetRow, pivotCol, idKTarget, idKPivot, idsResult, idFeedback, stepLvl) {
        let kTarg = parseFracObj(document.getElementById(idKTarget).value);
        let kPiv = parseFracObj(document.getElementById(idKPivot).value);
        let fb = document.getElementById(idFeedback);

        let userRow = [];
        for(let j=0; j<4; j++) {
            let uV = parseFracObj(document.getElementById(idsResult[j]).value);
            if(!uV) { fb.innerHTML = '<span class="sys-error">Completa la fila</span>'; return; }
            userRow.push(uV);
        }

        let isCorrect = true;
        let realRow = [];
        for(let j=0; j<4; j++) {
            realRow[j] = fAdd(fMul(kTarg, sysMatrix[targetRow][j]), fMul(kPiv, sysMatrix[pivotCol][j]));
            if(!fEqual(userRow[j], realRow[j])) isCorrect = false;
        }

        if(isCorrect) {
            fb.innerHTML = '<span class="sys-success">¡Fila perfecta!</span>';
            sysMatrix[targetRow] = realRow;
            sysUpdateDisplay();
            idsResult.forEach(id => document.getElementById(id).disabled = true);

            if(stepLvl === 1) {
                rowsCompletedStep1++;
                if(rowsCompletedStep1 === 2) {
                    document.getElementById('sys-paso2').style.display = 'block';
                    sysHighlight(1, 2);
                } else {
                    sysHighlight(0, targetRow === 1 ? 2 : 1); 
                }
            } else if (stepLvl === 2) {
                setupResolution();
            }
        } else {
            fb.innerHTML = '<span class="sys-error">Hay un error matemático</span>';
        }
    }

    // --- RESOLUCIÓN FINAL ---
    function setupResolution() {
        document.getElementById('sys-paso3').style.display = 'block';
        sysUpdateDisplay(); 

        // Escribir el SISTEMA TRIANGULADO 
        let eqHtml = "";
        for(let i=0; i<3; i++) {
            let terms = [];
            if(!fIsZero(sysMatrix[i][0])) terms.push(fFormatTerm(sysMatrix[i][0], "x"));
            if(!fIsZero(sysMatrix[i][1])) terms.push(fFormatTerm(sysMatrix[i][1], "y"));
            if(!fIsZero(sysMatrix[i][2])) terms.push(fFormatTerm(sysMatrix[i][2], "z"));

            let eq = terms.join("").trim();
            if(eq.startsWith("+")) eq = eq.substring(1).trim();
            if(eq === "") eq = "0";

            eqHtml += `<div>${eq} = ${formatFracVisual(sysMatrix[i][3])}</div>`;
        }
        document.getElementById('sys-triangulated-display').innerHTML = eqHtml;

        let eqZ = `${formatFracVisual(sysMatrix[2][2])}z = ${formatFracVisual(sysMatrix[2][3])}`;
        document.getElementById('eq-z').innerHTML = eqZ;

        let termY = formatFracVisual(sysMatrix[1][1]) + "y";
        let termZY = fFormatTerm(sysMatrix[1][2], "z");
        document.getElementById('eq-y').innerHTML = `${termY}${termZY} = ${formatFracVisual(sysMatrix[1][3])}`;

        let termX = formatFracVisual(sysMatrix[0][0]) + "x";
        let termYX = fFormatTerm(sysMatrix[0][1], "y");
        let termZX = fFormatTerm(sysMatrix[0][2], "z");
        document.getElementById('eq-x').innerHTML = `${termX}${termYX}${termZX} = ${formatFracVisual(sysMatrix[0][3])}`;
    }

    function sysCheckZ() {
        let uZ = parseFracObj(document.getElementById('sol-z').value);
        let fb = document.getElementById('res-sol-z');
        if(!uZ) { fb.innerHTML = '<span class="sys-error">Introduce valor</span>'; return; }

        let realZ = fDiv(sysMatrix[2][3], sysMatrix[2][2]);
        if(fEqual(uZ, realZ)) {
            fb.innerHTML = '<span class="sys-success">¡z correcto!</span>';
            document.getElementById('sol-z').disabled = true;
            document.getElementById('btn-sol-z').style.display = 'none';
            document.getElementById('box-sol-y').style.display = 'flex';
        } else {
            fb.innerHTML = '<span class="sys-error">Incorrecto</span>';
        }
    }

    function sysCheckY() {
        let uY = parseFracObj(document.getElementById('sol-y').value);
        let fb = document.getElementById('res-sol-y');
        if(!uY) { fb.innerHTML = '<span class="sys-error">Introduce valor</span>'; return; }

        let realZ = fDiv(sysMatrix[2][3], sysMatrix[2][2]);
        let rightSide = fSub(sysMatrix[1][3], fMul(sysMatrix[1][2], realZ));
        let realY = fDiv(rightSide, sysMatrix[1][1]);

        if(fEqual(uY, realY)) {
            fb.innerHTML = '<span class="sys-success">¡y correcto!</span>';
            document.getElementById('sol-y').disabled = true;
            document.getElementById('btn-sol-y').style.display = 'none';
            document.getElementById('box-sol-x').style.display = 'flex';
        } else {
            fb.innerHTML = '<span class="sys-error">Incorrecto</span>';
        }
    }

    function sysCheckX() {
        let uX = parseFracObj(document.getElementById('sol-x').value);
        let fb = document.getElementById('res-sol-x');
        if(!uX) { fb.innerHTML = '<span class="sys-error">Introduce valor</span>'; return; }

        let realZ = fDiv(sysMatrix[2][3], sysMatrix[2][2]);
        let rightSideY = fSub(sysMatrix[1][3], fMul(sysMatrix[1][2], realZ));
        let realY = fDiv(rightSideY, sysMatrix[1][1]);

        let rightSideX = fSub(fSub(sysMatrix[0][3], fMul(sysMatrix[0][2], realZ)), fMul(sysMatrix[0][1], realY));
        let realX = fDiv(rightSideX, sysMatrix[0][0]);

        if(fEqual(uX, realX)) {
            fb.innerHTML = '<span class="sys-success">¡x correcto!</span>';
            document.getElementById('sol-x').disabled = true;
            document.getElementById('btn-sol-x').style.display = 'none';
            document.getElementById('sys-final-msg').style.display = 'block';
        } else {
            fb.innerHTML = '<span class="sys-error">Incorrecto</span>';
        }
    }

    // Iniciar
    sysGenerar();
</script>
