<p>
<script>
    // --- MOTOR DE FRACCIONES EXACTAS ---
    function gcd(a, b) { a = Math.abs(a); b = Math.abs(b); while (b) { let t = b; b = a % b; a = t; } return a || 1; }
    function simplify(n, d) { if (n === 0) return {n: 0, d: 1}; if (d < 0) { n = -n; d = -d; } let g = gcd(n, d); return {n: n / g, d: d / g}; }
    function fAdd(a, b) { return simplify(a.n * b.d + b.n * a.d, a.d * b.d); }
    function fSub(a, b) { return simplify(a.n * b.d - b.n * a.d, a.d * b.d); }
    function fMul(a, b) { return simplify(a.n * b.n, a.d * b.d); }
    function fDiv(a, b) { return simplify(a.n * b.d, a.d * b.n); }
    function fEqual(a, b) { return a.n * b.d === b.n * a.d; }
    function fIsZero(a) { return a.n === 0; }
    function fAbs(a) { return {n: Math.abs(a.n), d: a.d}; }

    function parseFracObj(valStr) {
        if(!valStr || valStr.trim() === '') return {n:0, d:1};
        valStr = valStr.replace(/\s+/g, '').replace(',', '.');
        if(valStr.includes('/')) {
            let parts = valStr.split('/');
            if(parts.length !== 2) return null;
            let num = parseInt(parts[0]), den = parseInt(parts[1]);
            if(isNaN(num) || isNaN(den) || den === 0) return null;
            return simplify(num, den);
        }
        let val = parseFloat(valStr);
        if(isNaN(val)) return null;
        let str = val.toString();
        if (!str.includes('.')) return {n: parseInt(val), d: 1};
        let decs = str.split('.')[1].length;
        let d = Math.pow(10, decs);
        return simplify(Math.round(val * d), d);
    }

    function formatFracVisual(f) {
        if (f.n === 0) return "0";
        if (f.d === 1) return f.n.toString();
        let sign = f.n < 0 ? "-" : "";
        return `${sign}<div class="frac-css"><span class="fnum">${Math.abs(f.n)}</span><span class="fdn">${f.d}</span></div>`;
    }

    function formatFracInline(f) {
        if (f.n === 0) return "0";
        if (f.d === 1) return f.n.toString();
        return `${f.n}/${f.d}`;
    }

    // --- INTERFAZ ---
    const vars3 = ['x', 'y', 'z'];
    const vars4 = ['x', 'y', 'z', 't'];

    function gsBuildInputGrid() {
        let n = parseInt(document.getElementById('gs-dim').value);
        let vars = n === 3 ? vars3 : vars4;
        let container = document.getElementById('gs-input-container');

        // Llave SVG Dinámica: Se estira automáticamente usando Flexbox
        let svgBrace = `
            <svg viewBox="0 0 10 100" preserveAspectRatio="none" style="width: 18px; flex-shrink: 0; margin-right: 15px; overflow: visible; padding: 5px 0;">
                <path d="M 10,0 C 2,0 2,10 2,20 L 2,40 C 2,48 -2,50 -2,50 C -2,50 2,52 2,60 L 2,80 C 2,90 2,100 10,100" fill="none" stroke="#222" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linecap="round"/>
            </svg>
        `;

        let html = `
        <div style="display: flex; align-items: stretch; justify-content: center; width: 100%;">
            ${svgBrace}
            <div style="display: flex; flex-direction: column; gap: 10px; padding: 5px 0;">
        `;

        for(let i=0; i<n; i++) {
            html += `<div style="display: flex; align-items: center; justify-content: center; gap: 5px;">`;
            for(let j=0; j<n; j++) {
                html += `<input type="text" id="in-m${i}${j}" class="gs-input-val" value="0"> <span class="gs-var-label">${vars[j]}</span>`;
                if(j < n-1) html += `<span style="font-weight:bold; margin: 0 5px;">+</span>`;
            }
            html += `<span style="font-weight:bold; margin: 0 10px;">=</span> <input type="text" id="in-m${i}${n}" class="gs-input-val" value="0" style="border-color: #0056b3; background: #e6f2ff;">`;
            html += `</div>`;
        }

        html += `</div></div>`;
        container.innerHTML = html;
        document.getElementById('gs-solution-area').style.display = 'none';
    }

    function gsClear() {
        let inputs = document.querySelectorAll('.gs-input-val');
        inputs.forEach(inp => inp.value = '0');
        document.getElementById('gs-solution-area').style.display = 'none';
    }

    function printMatrixHTML(mat, pivotR = -1, pivotC = -1, highlightR = -1, highlightC = -1) {
        let n = mat.length;
        let html = `<div class="gs-matrix-view" style="grid-template-columns: repeat(${n+1}, minmax(40px, auto)); gap: 10px 20px;">`;
        for(let i=0; i<n; i++) {
            for(let j=0; j<=n; j++) {
                let style = "";
                if (j === n) style += "border-left: 2px dashed #ccc; padding-left: 15px; ";
                if (i === pivotR && j === pivotC) style += "color: #0056b3; font-weight: bold; ";
                else if (i === highlightR && j === highlightC) style += "color: #dc3545; font-weight: bold; ";

                html += `<div style="${style}">${formatFracVisual(mat[i][j])}</div>`;
            }
        }
        html += `</div>`;
        return html;
    }

    // --- ALGORITMO RESOLUTOR ---
    function gsSolve() {
        let n = parseInt(document.getElementById('gs-dim').value);
        let vars = n === 3 ? vars3 : vars4;
        let stepsHtml = '';
        let mat = [];

        for(let i=0; i<n; i++) {
            mat[i] = [];
            for(let j=0; j<=n; j++) {
                let val = parseFracObj(document.getElementById(`in-m${i}${j}`).value);
                if(!val) {
                    alert(`Error: Revisa el valor introducido en la fila ${i+1}, columna ${j+1}.`);
                    return;
                }
                mat[i].push(val);
            }
        }

        document.getElementById('gs-solution-area').style.display = 'flex';
        let stepsContainer = document.getElementById('gs-steps-container');

        stepsHtml += `
            <div class="gs-step-box">
                <div class="gs-step-title">Matriz Ampliada Inicial</div>
                <p style="margin-top:0;">Escribimos el sistema en forma de matriz ampliada (A|b):</p>
                <div style="text-align:center;">${printMatrixHTML(mat)}</div>
            </div>
        `;

        let stepCount = 1;

        for(let p=0; p<n-1; p++) {
            if(fIsZero(mat[p][p])) {
                let swapRow = -1;
                for(let r=p+1; r<n; r++) {
                    if(!fIsZero(mat[r][p])) { swapRow = r; break; }
                }
                if(swapRow !== -1) {
                    let temp = mat[p];
                    mat[p] = mat[swapRow];
                    mat[swapRow] = temp;
                    stepsHtml += `
                        <div class="gs-step-box">
                            <div class="gs-step-title">Intercambio de filas</div>
                            <p>Como el pivote en a<sub>${p+1}${p+1}</sub> es 0, intercambiamos la Fila ${p+1} con la Fila ${swapRow+1}:</p>
                            <div style="text-align:center;">${printMatrixHTML(mat, p, p)}</div>
                        </div>
                    `;
                } else {
                    continue; 
                }
            }

            let madeZeros = false;
            let opsHtml = `<ul style="line-height: 1.8;">`;

            for(let r=p+1; r<n; r++) {
                if(!fIsZero(mat[r][p])) {
                    madeZeros = true;
                    let factor = fDiv(mat[r][p], mat[p][p]);

                    let factStr = formatFracInline(factor);
                    let opStr = `F<sub>${r+1}</sub> &rarr; F<sub>${r+1}</sub> - (${factStr}) · F<sub>${p+1}</sub>`;
                    if(factor.n < 0) {
                        opStr = `F<sub>${r+1}</sub> &rarr; F<sub>${r+1}</sub> + (${formatFracInline(fAbs(factor))}) · F<sub>${p+1}</sub>`;
                    }

                    opsHtml += `<li><b>${opStr}</b> para hacer cero en a<sub>${r+1}${p+1}</sub></li>`;

                    for(let c=p; c<=n; c++) {
                        mat[r][c] = fSub(mat[r][c], fMul(factor, mat[p][c]));
                    }
                    mat[r][p] = {n:0, d:1}; 
                }
            }
            opsHtml += `</ul>`;

            if(madeZeros) {
                stepsHtml += `
                    <div class="gs-step-box">
                        <div class="gs-step-title">Paso ${stepCount}: Ceros en la columna ${p+1}</div>
                        <p>Tomamos como pivote a<sub>${p+1}${p+1}</sub> y operamos:</p>
                        ${opsHtml}
                        <div style="text-align:center; margin-top: 15px;">${printMatrixHTML(mat, p, p)}</div>
                    </div>
                `;
                stepCount++;
            }
        }

        // Comprobación de Rangos 
        let systemType = 1; 
        for(let i=0; i<n; i++) {
            let allZerosLeft = true;
            for(let j=0; j<n; j++) {
                if(!fIsZero(mat[i][j])) allZerosLeft = false;
            }
            if(allZerosLeft) {
                if(!fIsZero(mat[i][n])) {
                    systemType = -1; 
                    break;
                } else {
                    systemType = 0; 
                }
            }
        }

        if(systemType === -1) {
            stepsHtml += `
                <div class="gs-step-box" style="border-color: #dc3545; border-left-color: #dc3545;">
                    <div class="gs-step-title" style="color: #dc3545;">¡Atención! Sistema Incompatible</div>
                    <p>Al triangular hemos llegado a una fila donde todos los coeficientes de las incógnitas son 0, pero el término independiente no lo es (ej. <b>0 = k</b>). Esto es una contradicción matemática.</p>
                    <h3 style="text-align:center; color: #dc3545;">El sistema NO tiene solución.</h3>
                </div>
            `;
            stepsContainer.innerHTML = stepsHtml;
            return;
        }

        if(systemType === 0) {
            stepsHtml += `
                <div class="gs-step-box" style="border-color: #ffc107; border-left-color: #ffc107;">
                    <div class="gs-step-title" style="color: #d39e00;">Sistema Compatible Indeterminado</div>
                    <p>Al triangular hemos obtenido una fila completa de ceros (<b>0 = 0</b>). Esto significa que sobra una ecuación porque era combinación lineal de las demás.</p>
                    <h3 style="text-align:center; color: #d39e00;">El sistema tiene INFINITAS soluciones (depende de parámetros).</h3>
                </div>
            `;
            stepsContainer.innerHTML = stepsHtml;
            return;
        }

        // Sustitución hacia atrás (SCD)
        let solutions = Array(n).fill({n:0, d:1});
        let backSubHtml = '';

        for(let i=n-1; i>=0; i--) {
            let rightSide = mat[i][n];
            let subEq = `${formatFracInline(mat[i][i])}${vars[i]}`;
            let rightStrParts = [formatFracVisual(rightSide)];

            for(let j=i+1; j<n; j++) {
                if(!fIsZero(mat[i][j])) {
                    let termToSub = fMul(mat[i][j], solutions[j]);
                    rightSide = fSub(rightSide, termToSub);

                    let termSign = mat[i][j].n > 0 ? "-" : "+";
                    let valToPrint = formatFracVisual(fAbs(mat[i][j]));
                    rightStrParts.push(`${termSign} (${valToPrint} · ${formatFracInline(solutions[j])})`);
                }
            }

            solutions[i] = fDiv(rightSide, mat[i][i]);

            let rightSideStr = rightStrParts.length > 1 ? rightStrParts.join(" ") + ` = ${formatFracVisual(rightSide)}` : formatFracVisual(rightSide);

            backSubHtml += `
                <div style="background: #fdfdff; padding: 15px; border-radius: 4px; margin-bottom: 10px; border: 1px solid #e6e6ff;">
                    <div style="font-family: monospace; font-size: 1.1em; color: #666; margin-bottom: 8px;">De la Fila ${i+1}:</div>
                    <div style="font-size: 1.2em; display:flex; align-items:center; flex-wrap:wrap; gap:15px;">
                        <div>${subEq} = ${rightSideStr}</div>
                        <div style="color:#0056b3; font-weight:bold; display: flex; align-items: center;"> &rArr; <span style="margin-left: 8px;">${vars[i]} = ${formatFracVisual(solutions[i])}</span></div>
                    </div>
                </div>
            `;
        }

        stepsHtml += `
            <div class="gs-step-box" style="border-color: #28a745; border-left-color: #28a745;">
                <div class="gs-step-title" style="color: #28a745;">Resolución Final (Sustitución hacia atrás)</div>
                <p>El sistema es <b>Compatible Determinado</b>. Despejamos las incógnitas de abajo hacia arriba:</p>
                ${backSubHtml}

                <div style="margin-top: 25px; padding: 15px; background: #d4edda; border-radius: 6px; text-align: center; border: 1px solid #c3e6cb;">
                    <h3 style="color: #155724; margin-top: 0; margin-bottom: 15px;">Solución del Sistema:</h3>
                    <div style="display: flex; justify-content: center; gap: 30px; font-size: 1.4em; font-family: monospace;">
                        ${vars.map((v, i) => `<span><b>${v}</b> = ${formatFracVisual(solutions[i])}</span>`).join('')}
                    </div>
                </div>
            </div>
        `;

        stepsContainer.innerHTML = stepsHtml;
    }

    // Init interface
    gsBuildInputGrid();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
